// One codebase, two products, and only one of them was being worked on.
//
// `src/` is the web app that `main` deploys to app.houndstack.com. `ios/` is a
// native shell that bundles a BUILD of that same `src/` — and
// `ios/App/App/public` is gitignored and regenerated by every `cap sync`, so
// there is nowhere in `ios/` to put a React, layout or behaviour change. Every
// such fix has to live in `src/`, which means it is live on the web the moment
// it merges.
//
// The iOS QA pass on 2026-08-20 fixed seven faults. Five of the fixes were in
// shared code, and shipping them would have changed the hosted product as a
// side effect of work that was only ever about the phone: new safe-area
// padding, a different invoice layout on narrow screens, new timeouts on the
// live sign-in path. Owner decision (2026-08-21): they must not.
//
// This file is the invariant. It does not care whether any individual fix is
// right — the other test files do that. It cares that the switch is real, that
// it is decided at build time, and that nobody has quietly added a sixth
// divergence without one.
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const root = process.cwd();
const read = (p: string) => readFileSync(join(root, p), "utf8");

const codeOnly = (src: string) =>
  src.replace(/\/\*[\s\S]*?\*\//g, "").replace(/(^|[^:])\/\/.*$/gm, "$1");

describe("the switch itself", () => {
  it("is decided at build time, not at runtime", () => {
    // A runtime check would still SHIP both branches to the web bundle, where a
    // later refactor could enable the native one. A define folds the branch out
    // of the hosted build entirely.
    const src = codeOnly(read("src/lib/native-build.ts"));
    expect(src).toMatch(/import\.meta\.env\.VITE_NATIVE_BUNDLE/);
    expect(src, "IS_NATIVE_BUNDLE now depends on something runtime").not.toMatch(
      /Capacitor|isNativePlatform|navigator/,
    );
  });

  it("is only ever defined for the native build", () => {
    // If this define escaped the NATIVE_BUILD branch, every gate in the repo
    // would switch on for app.houndstack.com at once.
    const cfg = read("vite.config.ts");
    const at = cfg.indexOf("VITE_NATIVE_BUNDLE");
    expect(at, "the define is gone — retarget this test").toBeGreaterThan(-1);
    // Walk back to the nearest NATIVE_BUILD guard and make sure one exists
    // between the top of the vite block and the define.
    const before = cfg.slice(0, at);
    expect(
      before.lastIndexOf("NATIVE_BUILD"),
      "VITE_NATIVE_BUNDLE is no longer inside a NATIVE_BUILD branch",
    ).toBeGreaterThan(-1);
    expect(before.lastIndexOf("NATIVE_BUILD")).toBeGreaterThan(before.lastIndexOf("plugins: ["));
  });

  it("is a different key from the API origin, on purpose", () => {
    // The origin answers "where do server functions go". This answers "may I
    // change how the product looks". Overloading one on the other would mean a
    // staging origin silently switching UI branches on.
    const cfg = read("vite.config.ts");
    expect(cfg).toMatch(/VITE_NATIVE_API_ORIGIN/);
    expect(cfg).toMatch(/VITE_NATIVE_BUNDLE/);
    expect(codeOnly(read("src/lib/native-build.ts"))).not.toMatch(/VITE_NATIVE_API_ORIGIN/);
  });
});

describe("every shared file the iOS pass touched carries a gate", () => {
  // Each entry is a file the 2026-08-20 pass changed that also ships to the
  // web, with the thing the native build does differently. If a fix here is
  // ever meant to apply to the web too, delete its row deliberately — do not
  // let it drift.
  const GATED = [
    ["src/routes/__root.tsx", "viewport-fit=cover"],
    ["src/components/PublicShell.tsx", "safe-area padding on the signed-out shell"],
    ["src/components/client-detail/billing-panels.tsx", "invoice cards below md"],
    ["src/components/StaffInvoicePayForm.tsx", "a deadline on the payment intent"],
    ["src/components/client-detail/BillingTab.tsx", "a deadline on the setup intent"],
    ["src/routes/auth.tsx", "the offline-tolerant landing bounce"],
    ["src/routes/_authenticated/route.tsx", "the native-aware offline signal"],
    ["src/lib/offline/identity.ts", "deadlines and the native-aware offline signal"],
    ["src/routes/platform.tsx", "the sticky top bar's status-bar inset"],
    ["src/routes/_authenticated/my-day.tsx", "the sticky top bar's status-bar inset"],
  ] as const;

  for (const [file, what] of GATED) {
    it(`${file.split("/").pop()} gates ${what}`, () => {
      const src = codeOnly(read(file));
      // Either directly, or through a helper that carries the gate itself —
      // `nativeTopBarStyle` returns undefined off-native, which is how three
      // headers share one spelling of the same divergence.
      expect(src, `${file} changed for iOS without going through the gate`).toMatch(
        /from "@\/lib\/native-build"/,
      );
    });
  }

  it("the shared top-bar helper is itself gated", () => {
    const src = codeOnly(read("src/lib/native-build.ts"));
    const fn = src.slice(src.indexOf("export function nativeTopBarStyle"));
    expect(fn.slice(0, 200), "nativeTopBarStyle no longer returns undefined off-native").toMatch(
      /if \(!IS_NATIVE_BUNDLE\) return undefined;/,
    );
  });

  it("all three sticky headers use it, so they cannot drift apart again", () => {
    // My Day solved this alone once, with its own inline style, while the two
    // shells went without. That is how the staff shell shipped a top bar whose
    // controls sat under the clock the moment a page scrolled.
    for (const f of [
      "src/routes/_authenticated/route.tsx",
      "src/routes/platform.tsx",
      "src/routes/_authenticated/my-day.tsx",
    ]) {
      expect(codeOnly(read(f)), `${f} no longer uses the shared top-bar style`).toMatch(
        /nativeTopBarStyle\(/,
      );
    }
  });
});

describe("what the hosted app still gets", () => {
  it("the viewport it always had", () => {
    const src = codeOnly(read("src/routes/__root.tsx"));
    const at = src.indexOf('name: "viewport"');
    const block = src.slice(at, at + 500);
    // Both branches present, and the fallback one is the original string.
    expect(block).toMatch(/"width=device-width, initial-scale=1"/);
  });

  it("the flat spacing on the signed-out shell", () => {
    const src = codeOnly(read("src/components/PublicShell.tsx"));
    expect(src).toMatch(/\bpx-4\b/);
    expect(src).toMatch(/\bpy-10\b/);
  });

  it("the invoice table on the client billing tab", () => {
    const src = codeOnly(read("src/components/client-detail/billing-panels.tsx"));
    expect(src, "the web lost the invoices table").toMatch(/<table/);
  });

  it("un-deadlined Stripe calls", () => {
    // The hang is a real fault and it is still there on the web, deliberately —
    // fixing it is a change to the hosted product and wants its own decision.
    for (const f of [
      "src/components/StaffInvoicePayForm.tsx",
      "src/components/client-detail/BillingTab.tsx",
    ]) {
      const src = codeOnly(read(f));
      expect(src, `${f} no longer has a web path that skips the deadline`).toMatch(
        /if \(!IS_NATIVE_BUNDLE\) return/,
      );
    }
  });

  // "The sign-in bounce it always had" was pinned here until #661. That bounce
  // was a bare getUser() that stopped on a failed request, which parked a
  // signed-in web user on /auth with the API down until a reload. The web now
  // lands through the shared resolver; see
  // tests/a-web-cold-start-with-the-api-down.test.ts.
});
